import 'package:cubes/cubes.dart';
import 'package:flutter/material.dart';

void main(){
  Cubes.registerFactory((i)=>CounterCube());
  runApp(MaterialApp(home: CounterScreen()));
}

class CounterCube extends Cube{final count=0.obs;void increment()=>count.modify((v)=>v+1);}

class CounterScreen extends CubeWidget<CounterCube>{
  const CounterScreen({Key?key}):super(key:key);
  @override
  Widget buildView(BuildContext ctx, CounterCube c){
    return Scaffold(
      body: Center(child: c.count.build<int>((v)=>Text('$v'))),
      floatingActionButton: FloatingActionButton(onPressed:c.increment,child:Icon(Icons.add)),
    );
  }
}
